# Phase 47 (#21) — the vegetated land column against FLUXNET eddy
# covariance, through the PLUMBER2 forcing/evaluation files (a validation
# run; the column, both stomatal closures included, is unit-tested in
# test/era5_land_surface.jl).
#
# DATA (validation/data/fluxnet/*.csv, regenerated by fetch_plumber2.jl there):
#   Ukkola, A. & Abramowitz, G. (2020). PLUMBER2: forcing and evaluation
#   datasets for a model intercomparison project for land surface models,
#   v1.0. NCI, doi:10.25914/5fdb0902607e1 (licence CC BY 4.0), derived from
#   FLUXNET2015 Tier 1 (Pastorello et al. 2020, Sci. Data 7, 225). Hourly
#   means of the half-hourly gap-filled meteorology (forcing) and of the
#   measured fluxes; only hours whose two half hours are both *measured*
#   (quality flag 0) are used for evaluation. Qle_cor/Qh_cor are the
#   PLUMBER2 energy-balance-closure-corrected fluxes (Bowen ratio kept).
#
# What is and is not observation here:
#   * forcing, LAI (Copernicus), canopy and measurement heights: from the
#     files;
#   * soil texture: from the site metadata where it is given (DE-Hai clay
#     40 %, sand 4 %; DE-Gri silty loam; FI-Hyy sandy/silty till → sandy
#     loam); otherwise a loam — an assumption;
#   * initial soil water (field capacity, −3.37 m), soil temperature (the
#     first day's mean air temperature), stem area (zero) and the use of
#     the CLM4.5 PFT parameters without any site calibration: model
#     choices, not data;
#   * the local-standard-time offsets are the sites' time zones (UTC+1
#     Germany/France, UTC+2 Finland, UTC−3 French Guiana); the test checks
#     them against the phase of the measured shortwave.

using Test
using Aeolus
using Aeolus.LandSurface
using Aeolus.SoilColumn: SoilThermalColumn
using Aeolus.SolarGeometry: solar_time, solar_position, partition_global_irradiance
using Dates, Printf

const FLUXNET_DIR = joinpath(@__DIR__, "data", "fluxnet")

# site => (PFT, (sand %, clay %), texture source, UTC offset of LST, spin-up days)
const FLUXNET_SITES = Dict(
    "DE-Hai" => (pft = :bdt_temperate, sand = 4.0, clay = 40.0, soil = "metadata", utc = 1, spin = 5),
    "FI-Hyy" => (pft = :net_boreal,    sand = 65.0, clay = 10.0, soil = "sandy loam (metadata: sandy/silty till)", utc = 2, spin = 5),
    "GF-Guy" => (pft = :bet_tropical,  sand = 40.0, clay = 20.0, soil = "loam (assumed)", utc = -3, spin = 5),
    "DE-Gri" => (pft = :c3_grass,      sand = 20.0, clay = 15.0, soil = "silt loam (metadata)", utc = 1, spin = 5),
    "FR-Pue" => (pft = :bet_temperate, sand = 40.0, clay = 20.0, soil = "loam (assumed)", utc = 1, spin = 5),
)

function _plumber_read(site)
    path = joinpath(FLUXNET_DIR, "$site.csv")
    meta = Dict{String,String}()
    header = String[]
    rows = Vector{Vector{Float64}}()
    for line in eachline(path)
        if startswith(line, "#")
            for m in eachmatch(r"(\w+)=(\S+)", line)
                meta[m[1]] = m[2]
            end
        elseif isempty(header)
            header = split(line, ",")
        else
            push!(rows, [x == "NaN" ? NaN : parse(Float64, x) for x in split(line, ",")])
        end
    end
    cols = Dict(h => [r[i] for r in rows] for (i, h) in enumerate(header))
    return meta, cols
end

"Run the land column over a site window; returns model hourly H, LE, Rn, G and diagnostics."
function _plumber_run(site; model = :medlyn, dt = 3600.0)
    meta, d = _plumber_read(site)
    cfg = FLUXNET_SITES[site]
    lat, lon = parse(Float64, meta["lat"]), parse(Float64, meta["lon"])
    zref, hc = parse(Float64, meta["reference_height"]), parse(Float64, meta["canopy_height"])
    co2 = parse(Float64, meta["co2_mean"])
    t0 = DateTime(meta["start"][1:16], dateformat"yyyy-mm-ddTHH:MM")
    n = length(d["hour"])
    Tair0 = sum(d["Tair"][1:24]) / 24
    grid = clm5_soil_grid(13)
    w = SoilWaterColumn(grid, cosby_clapp_hornberger(cfg.sand, cfg.clay); ψ = -3.37,
                        ice_impedance = PowerLawIceImpedance())
    soil = SoilThermalColumn(w, clm_soil_thermal_properties(cfg.sand, cfg.clay); T_soil = Tair0)
    col = VegetatedLandColumn(soil, pft_vegetation(cfg.pft; model = model);
                              LAI = d["LAI"][1], SAI = 0.0, z_top = hc, co2 = co2,
                              T_veg = Tair0, q_ac = d["Qair"][1] / 1000)
    out = (H = zeros(n), LE = zeros(n), Rn = zeros(n), G = zeros(n), βt = zeros(n),
           Et = zeros(n), GPP = zeros(n), conv = falses(n), res = zeros(n),
           diag = Vector{LandSurfaceDiagnostics}(undef, n))
    for k in 1:n
        # interval [t, t+1 h) in local standard time; sun at its middle, in UTC
        tm = t0 + Minute(60 * (k - 1) + 30) - Hour(cfg.utc)
        st = solar_time(year(tm), month(tm), day(tm), hour(tm), minute(tm), 0.0;
                        latitude = lat, longitude = lon)
        pos = solar_position(st)
        sw = max(d["SWdown"][k], 0.0)
        fdif = sw > 0 && pos.μ₀ > 0.02 ? partition_global_irradiance(sw, pos).diffuse_fraction : 1.0
        set_leaf_area!(col, d["LAI"][k])
        f = SurfaceForcing(sw_down = sw, lw_down = d["LWdown"][k], T_air = d["Tair"][k],
                           q_air = d["Qair"][k] / 1000, U = max(d["Wind"][k], 0.1),
                           p = 100 * d["Psurf"][k], z_ref = zref,
                           rain = d["Precip"][k] / 3600, snow = 0.0)
        fl = step_surface!(col, f, dt; cosz = max(pos.μ₀, 0.0), diffuse_fraction = fdif)
        l = col.last
        out.H[k], out.LE[k], out.Rn[k], out.G[k] = fl.H, fl.LE, fl.Rn, fl.G
        out.βt[k], out.Et[k], out.GPP[k], out.conv[k], out.res[k] = l.β_t, l.E_t, l.GPP, l.converged,
                                                                      fl.Rn - fl.H - fl.LE - fl.G
        out.diag[k] = l
    end
    return meta, d, out, col
end

_pl_mean(x) = sum(x) / length(x)
function _pl_stats(m, o)
    b = _pl_mean(m .- o)
    rmse = sqrt(_pl_mean((m .- o) .^ 2))
    mm, mo = _pl_mean(m), _pl_mean(o)
    r = sum((m .- mm) .* (o .- mo)) / sqrt(sum((m .- mm) .^ 2) * sum((o .- mo) .^ 2))
    return (bias = b, rmse = rmse, r = r)
end
# PLUMBER "1lin" benchmark: in-sample linear regression of the flux on SWdown.
function _pl_onelin_rmse(sw, o)
    ms, mo = _pl_mean(sw), _pl_mean(o)
    a = sum((sw .- ms) .* (o .- mo)) / sum((sw .- ms) .^ 2)
    return sqrt(_pl_mean((mo .+ a .* (sw .- ms) .- o) .^ 2))
end

# Daytime evaporative fraction Σ LE / Σ(H + LE) over hours with both fluxes
# measured and SWdown > 50 W m⁻²; unchanged by the Bowen-ratio-preserving
# closure correction, so it compares directly with a model that closes.
function _pl_daytime_ef(idx, d, o)
    day = [k for k in idx if d["SWdown"][k] > 50]
    return sum(o.LE[day]) / (sum(o.LE[day]) + sum(o.H[day])),
           sum(d["Qle"][day]) / (sum(d["Qle"][day]) + sum(d["Qh"][day]))
end

@testset "FLUXNET (PLUMBER2) validation of the land column" begin
    results = Dict{String,Any}()
    for site in ("DE-Hai", "FI-Hyy", "GF-Guy", "DE-Gri", "FR-Pue")
        meta, d, o, col = _plumber_run(site)
        cfg = FLUXNET_SITES[site]
        n = length(d["hour"])
        ev = (cfg.spin * 24 + 1):n

        # --- the data: local standard time agrees with the sun ------------
        # centroid of the mean diurnal shortwave vs solar noon (SolarGeometry)
        lat, lon = parse(Float64, meta["lat"]), parse(Float64, meta["lon"])
        comp = [sum(d["SWdown"][h+1:24:n]) for h in 0:23]
        centroid = sum((h + 0.5) * comp[h+1] for h in 0:23) / sum(comp)
        t0 = DateTime(meta["start"][1:16], dateformat"yyyy-mm-ddTHH:MM") + Day(n ÷ 48)
        μ(mins) = (tm = t0 + Minute(mins) - Hour(cfg.utc);
                   solar_position(solar_time(year(tm), month(tm), day(tm), hour(tm), minute(tm), 0.0;
                                             latitude = lat, longitude = lon)).μ₀)
        noon = argmax(μ, 540:900) / 60
        @test abs(centroid - noon) < 0.5

        # --- the model: closes energy every hour ----------------------------
        @test maximum(abs, o.res) < 1e-9
        @test count(o.conv) / n > 0.95
        # hours where the canopy iteration hit maxiter were still settled to < 0.05 K
        # (measured worst: 0.026 K, FR-Pue, calm dawn with u* = 0.05 m s⁻¹)
        @test all(k -> o.conv[k] || o.diag[k].last_change < 0.05, 1:n)

        # --- against the measured fluxes ------------------------------------
        st = Dict{String,Any}()
        for (name, mv, ov, q) in (("LE", o.LE, d["Qle"], d["Qle_qc"]), ("H", o.H, d["Qh"], d["Qh_qc"]),
                                  ("Rn", o.Rn, d["Rnet"], zeros(n)))
            idx = [k for k in ev if q[k] == 0 && isfinite(ov[k])]
            st[name] = merge(_pl_stats(mv[idx], ov[idx]),
                             (n = length(idx), mod = _pl_mean(mv[idx]), obs = _pl_mean(ov[idx]),
                              onelin = _pl_onelin_rmse(d["SWdown"][idx], ov[idx])))
        end
        both = [k for k in ev if d["Qle_qc"][k] == 0 && d["Qh_qc"][k] == 0]
        cor = [k for k in both if isfinite(d["Qle_cor"][k])]
        EFm, EFo = _pl_daytime_ef(both, d, o)
        LEcor_bias = isempty(cor) ? NaN : _pl_mean(o.LE[cor] .- d["Qle_cor"][cor])   # GF-Guy: no corrected fluxes
        results[site] = (st = st, EFm = EFm, EFo = EFo, LEcor_bias = LEcor_bias,
                         βt = _pl_mean(o.βt[ev]), conv = count(o.conv) / n, d = d, o = o)
        @info "FLUXNET $site ($(meta["igbp"]), $(cfg.pft), soil $(cfg.soil))" LE = st["LE"] H = st["H"] Rn = st["Rn"] EF_model = EFm EF_obs = EFo LE_bias_vs_closure_corrected = LEcor_bias mean_βt = results[site].βt converged = results[site].conv

        # Regression guards set around the measured values (see the PR):
        # net radiation is reproduced closely everywhere; the diurnal cycle
        # of LE is well correlated; the evaporative fraction is within 0.05
        # at FI-Hyy and GF-Guy and too high (wet bias) at the other sites.
        @test st["Rn"].r > 0.97 && abs(st["Rn"].bias) < 15
        @test st["LE"].r > 0.8
        @test st["H"].r > 0.5
        @test abs(EFm - EFo) < 0.4
    end
    # The CLM4.5 Ball-Berry closure instead of CLM5's Medlyn (same column,
    # same parameters otherwise), reported for comparison.
    for site in ("DE-Hai", "FI-Hyy", "GF-Guy", "DE-Gri", "FR-Pue")
        meta, d, o, _ = _plumber_run(site; model = :ball_berry)
        ev = (FLUXNET_SITES[site].spin * 24 + 1):length(d["hour"])
        both = [k for k in ev if d["Qle_qc"][k] == 0 && d["Qh_qc"][k] == 0]
        EFm, EFo = _pl_daytime_ef(both, d, o)
        idx = [k for k in ev if d["Qle_qc"][k] == 0]
        @info "FLUXNET $site with Ball-Berry stomata" EF_model = EFm EF_obs = EFo LE = _pl_stats(o.LE[idx], d["Qle"][idx])
        @test maximum(abs, o.res) < 1e-9
    end
    @test abs(results["FI-Hyy"].EFm - results["FI-Hyy"].EFo) < 0.05
    @test abs(results["GF-Guy"].EFm - results["GF-Guy"].EFo) < 0.05

    # --- drought at Puéchabon, May-August 2006 ------------------------------
    # midday (10-15 h) Bowen ratio per month, hours with both fluxes measured
    r = results["FR-Pue"]
    d, o = r.d, r.o
    bounds = cumsum([0, 31, 30, 31, 31]) .* 24
    Bo, Bm, β = Float64[], Float64[], Float64[]
    for m in 1:4
        ks = [k for k in bounds[m]+1:bounds[m+1] if 10 <= (k - 1) % 24 <= 14 &&
              d["Qle_qc"][k] == 0 && d["Qh_qc"][k] == 0]
        push!(Bo, sum(d["Qh"][ks]) / sum(d["Qle"][ks]))
        push!(Bm, sum(o.H[ks]) / sum(o.LE[ks]))
        push!(β, _pl_mean(o.βt[ks]))
    end
    @info "FR-Pue 2006, midday Bowen ratio May/Jun/Jul/Aug" observed = Tuple(round.(Bo; digits = 2)) modelled = Tuple(round.(Bm; digits = 2)) βt = Tuple(round.(β; digits = 3))
    # The drying soil raises the Bowen ratio from May to July in both.
    @test Bo[3] > Bo[2] > Bo[1]
    @test Bm[3] > Bm[2] > Bm[1]
    @test β[3] < β[2] < β[1]
end
